css:
.container {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.drop-area {
  border: 2px dashed #444;
  border-radius: 12px;
  padding: 16px;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
  background-color: #1a1a1a;
}

.file-input {
  display: none;
}

.file-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.file-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.file-title {
  font-size: 14px;
  font-weight: 500;
  color: #ccc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.add-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  font-size: 14px;
  color: #ccc;
  border: 1px solid #555;
  border-radius: 6px;
  background-color: transparent;
  cursor: pointer;
}

.add-button:hover {
  background-color: #2a2a2a;
}

.icon {
  width: 18px;
  height: 18px;
  opacity: 0.6;
}

.file-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
  gap: 16px;
}

.file-box {
  position: relative;
  width: 100px;
  height: 100px;
  background-color: #2a2a2a;
  border-radius: 8px;
}

.preview-box {
  width: 100%;
  height: 100%;
  background-color: #444;
  border-radius: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #aaa;
}

.remove-button {
  position: absolute;
  top: -8px;
  right: -8px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background-color: white;
  color: black;
  border: 2px solid white;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.remove-button .icon {
  width: 14px;
  height: 14px;
  opacity: 1;
}
